package io.github.deepseekbridge;

import android.content.Context;
import android.net.Uri;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import java.util.zip.*;

/** Encrypted configuration and native transports for the isolated MCP worker. */
final class ExtensionHub implements AutoCloseable {
    interface Child {InputStream stdout();InputStream stderr();OutputStream stdin();int await()throws Exception;void stop();}
    interface Launcher {Child open(String project,JSONObject config)throws Exception;}
    interface Events {void emit(JSONObject value);}
    final Context context;final LocalState vault;final Launcher launcher;final Events events;final File directory;
    private final ExecutorService io=Executors.newCachedThreadPool(r->new Thread(r,"studio-extension-io"));
    private final Map<String,HttpURLConnection> http=new ConcurrentHashMap<>();
    private final Map<String,String> httpServers=new ConcurrentHashMap<>();
    private final Map<String,Pipe> pipes=new ConcurrentHashMap<>();
    private JSONObject config;private volatile boolean closed;private volatile String session="";
    static final class Pipe {final String server,project;final Child child;Pipe(String s,String p,Child c){server=s;project=p;child=c;}}
    ExtensionHub(Context c,Launcher l,Events e){this(c,new LocalState(c,"studio-extensions-v1","studio-extensions-v1"),l,e);}
    ExtensionHub(Context c,LocalState v,Launcher l,Events e){context=c;vault=v;launcher=l;events=e;directory=new File(c.getFilesDir(),"studio-plugins");try{config=new JSONObject(vault.load());}catch(Exception ignored){config=new JSONObject();}}
    private JSONArray records(String key){JSONArray values=config.optJSONArray(key);return values==null?new JSONArray():values;}
    private void save(JSONObject next)throws IOException {if(!vault.save(next.toString()))throw new IOException("扩展配置无法加密保存");config=next;}
    static JSONObject normalize(JSONObject a)throws Exception {
        String id=a.optString("id",UUID.randomUUID().toString()),type=a.optString("type",a.has("url")?"http":"stdio");
        if(!id.matches("[A-Za-z0-9_-]{1,64}")||!Arrays.asList("http","stdio").contains(type))throw new IOException("无效的 MCP 配置");
        JSONObject out=new JSONObject().put("id",id).put("name",a.optString("name","MCP 服务").substring(0,Math.min(80,a.optString("name","MCP 服务").length()))).put("type",type).put("enabled",a.optBoolean("enabled",false));
        if(a.has("plugin"))out.put("plugin",a.getString("plugin"));
        if(type.equals("http")){URI u=new URI(a.getString("url"));if(!Arrays.asList("https","http").contains(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null||u.getFragment()!=null||u.getHost().equalsIgnoreCase("bridge.local")||u.toString().length()>4096)throw new IOException("MCP 地址须为 HTTP(S) 服务端点");out.put("url",u.toString());JSONObject headers=a.optJSONObject("headers");headers=headers==null?new JSONObject():headers;if(headers.length()>16)throw new IOException("请求头过多");for(Iterator<String> k=headers.keys();k.hasNext();){String name=k.next(),value=headers.getString(name);if(!name.matches("[A-Za-z0-9-]{1,80}")||value.length()>4096||value.indexOf('\r')>=0||value.indexOf('\n')>=0||Arrays.asList("host","content-length","cookie").contains(name.toLowerCase(Locale.ROOT)))throw new IOException("不支持的 MCP 请求头");}out.put("headers",headers);}
        else {String command=a.getString("command");if(command.isEmpty()||command.length()>2048||command.indexOf('\0')>=0)throw new IOException("请填写可执行程序");JSONArray args=a.optJSONArray("args");args=args==null?new JSONArray():args;if(args.length()>128)throw new IOException("启动参数过多");for(int i=0;i<args.length();i++)if(!(args.get(i) instanceof String)||args.getString(i).length()>8192||args.getString(i).indexOf('\0')>=0)throw new IOException("无效启动参数");JSONObject env=a.optJSONObject("env");env=env==null?new JSONObject():env;if(env.length()>32)throw new IOException("环境变量过多");for(Iterator<String> k=env.keys();k.hasNext();){String name=k.next();if(!name.matches("[A-Za-z_][A-Za-z0-9_]{0,79}")||env.getString(name).length()>8192||env.getString(name).indexOf('\0')>=0)throw new IOException("无效环境变量");}out.put("command",command).put("args",args).put("env",env);}
        return out;
    }
    synchronized JSONObject snapshot()throws Exception {JSONArray values=new JSONArray();for(int i=0;i<records("servers").length();i++){JSONObject p=new JSONObject(records("servers").getJSONObject(i).toString());p.put("hasSecret",p.optJSONObject("headers")!=null&&p.getJSONObject("headers").length()>0||p.optJSONObject("env")!=null&&p.getJSONObject("env").length()>0);String revision=hex(MessageDigest.getInstance("SHA-256").digest(p.toString().getBytes(StandardCharsets.UTF_8)));p.remove("headers");p.remove("env");p.put("revision",revision);values.put(p);}return new JSONObject().put("servers",values).put("plugins",records("plugins"));}
    synchronized JSONObject server(String id)throws Exception {if(closed)throw new IOException("扩展服务已关闭");for(int i=0;i<records("servers").length();i++){JSONObject p=records("servers").getJSONObject(i);if(id.equals(p.optString("id"))){if(!p.optBoolean("enabled"))throw new IOException("该 MCP 服务已停用");return new JSONObject(p.toString());}}throw new IOException("MCP 配置不存在");}
    synchronized JSONObject upsert(JSONObject input)throws Exception {JSONObject raw=new JSONObject(input.toString());for(int i=0;i<records("servers").length();i++){JSONObject old=records("servers").getJSONObject(i);if(old.optString("id").equals(raw.optString("id"))&&!raw.optBoolean("clearSecrets")){for(String key:new String[]{"headers","env"})if(!raw.has(key)&&old.has(key))raw.put(key,old.get(key));}}JSONObject p=normalize(raw);JSONArray next=new JSONArray();boolean found=false;for(int i=0;i<records("servers").length();i++){JSONObject old=records("servers").getJSONObject(i);if(old.getString("id").equals(p.getString("id"))){found=true;next.put(p);}else next.put(old);}if(!found){if(next.length()>=16)throw new IOException("最多保存 16 个 MCP 服务");next.put(p);}JSONObject n=new JSONObject(config.toString()).put("servers",next);save(n);stopServer(p.getString("id"));return snapshot();}
    synchronized JSONObject toggle(String id,boolean enabled,boolean remove)throws Exception {JSONArray next=new JSONArray();for(int i=0;i<records("servers").length();i++){JSONObject p=new JSONObject(records("servers").getJSONObject(i).toString());if(id.equals(p.optString("id"))){if(remove)continue;p.put("enabled",enabled);}next.put(p);}save(new JSONObject(config.toString()).put("servers",next));stopServer(id);return snapshot();}
    synchronized JSONObject importServers(JSONArray input)throws Exception {if(input.length()<1||input.length()+records("servers").length()>16)throw new IOException("最多保存 16 个 MCP 服务");JSONArray next=new JSONArray(records("servers").toString());for(int i=0;i<input.length();i++){JSONObject value=new JSONObject(input.getJSONObject(i).toString());value.remove("id");value.remove("plugin");next.put(normalize(value));}save(new JSONObject(config.toString()).put("servers",next));return snapshot();}
    private void emit(String id,String event,Object data){try{events.emit(new JSONObject().put("type","extension").put("id",id).put("event",event).put("data",data));}catch(JSONException ignored){}}
    static String hex(byte[] data){StringBuilder b=new StringBuilder();for(byte value:data)b.append(String.format(Locale.ROOT,"%02x",value&255));return b.toString();}
    static URL checkedUrl(JSONObject server,String raw)throws Exception {URI base=new URI(server.getString("url")),u=new URI(raw);if(!Objects.equals(base.getScheme(),u.getScheme())||!Objects.equals(base.getHost(),u.getHost())||base.getPort()!=u.getPort()||!Objects.equals(base.getRawPath(),u.getRawPath())||u.getUserInfo()!=null||u.getFragment()!=null)throw new IOException("MCP 请求离开已配置端点，未发送凭据");return u.toURL();}
    void http(String id,JSONObject a)throws Exception {
        JSONObject s=server(a.getString("server"));URL url=checkedUrl(s,a.getString("url"));String method=a.optString("method","POST");if(!Arrays.asList("GET","POST","DELETE").contains(method))throw new IOException("MCP HTTP 方法不支持");String body=a.optString("body");if(body.length()>2000000||http.size()>=12)throw new IOException("MCP 请求超过容量");HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(60000);c.setRequestMethod(method);JSONObject headers=a.optJSONObject("headers");if(headers!=null)for(Iterator<String> keys=headers.keys();keys.hasNext();){String key=keys.next();if(key.equalsIgnoreCase("accept")||key.equalsIgnoreCase("content-type")||key.toLowerCase(Locale.ROOT).startsWith("mcp-")){String value=headers.getString(key);if(value.indexOf('\r')>=0||value.indexOf('\n')>=0)throw new IOException("无效请求头");c.setRequestProperty(key,value);}}JSONObject secret=s.optJSONObject("headers");if(secret!=null)for(Iterator<String> keys=secret.keys();keys.hasNext();){String key=keys.next();c.setRequestProperty(key,secret.getString(key));}if(http.putIfAbsent(id,c)!=null)throw new IOException("重复 MCP 传输 ID");httpServers.put(id,s.getString("id"));
        io.execute(()->{try{if(http.get(id)!=c||!server(s.getString("id")).toString().equals(s.toString()))throw new IOException("MCP 配置已变化");if(method.equals("POST")){byte[] bytes=body.getBytes(StandardCharsets.UTF_8);c.setDoOutput(true);c.setFixedLengthStreamingMode(bytes.length);try(OutputStream out=c.getOutputStream()){out.write(bytes);}}int status=c.getResponseCode();JSONObject h=new JSONObject();for(Map.Entry<String,List<String>> entry:c.getHeaderFields().entrySet())if(entry.getKey()!=null)h.put(entry.getKey(),String.join(", ",entry.getValue()));emit(id,"headers",new JSONObject().put("status",status).put("headers",h));if(status!=204&&status!=205&&status!=304){InputStream source=status>=400?c.getErrorStream():c.getInputStream();if(source!=null)try(Reader in=new InputStreamReader(source,StandardCharsets.UTF_8)){char[] chunk=new char[4096];int count,total=0;while((count=in.read(chunk))!=-1){total+=count;if(total>8388608)throw new IOException("MCP 响应超过 8 MB");emit(id,"data",new String(chunk,0,count));}}}emit(id,"end",true);}catch(Exception e){emit(id,"error","MCP HTTP 传输中断；请检查服务状态，未自动重试工具");}finally{http.remove(id,c);httpServers.remove(id);c.disconnect();}});
    }
    JSONObject open(String project,String serverId)throws Exception {JSONObject s=server(serverId);if(!s.getString("type").equals("stdio"))throw new IOException("此服务不是 stdio");if(pipes.size()>=4)throw new IOException("最多同时运行 4 个 stdio 服务");String openingSession=session;Child child=launcher.open(project,s);synchronized(this){try{if(!session.equals(openingSession))throw new IOException("MCP 会话在启动时结束");if(!server(serverId).toString().equals(s.toString()))throw new IOException("MCP 配置在启动时变化");}catch(Exception e){child.stop();throw e;}String id="pipe-"+UUID.randomUUID();Pipe p=new Pipe(serverId,project,child);pipes.put(id,p);return watchPipe(id,p);} }
    private JSONObject watchPipe(String id,Pipe p)throws Exception {Child child=p.child;io.execute(()->{try(Reader in=new InputStreamReader(child.stdout(),StandardCharsets.UTF_8)){StringBuilder line=new StringBuilder();char[] chunk=new char[4096];int n;while((n=in.read(chunk))!=-1){line.append(chunk,0,n);if(line.length()>1048576)throw new IOException("MCP 单条消息超过 1 MB");int end;while((end=line.indexOf("\n"))>=0){String value=line.substring(0,end).trim();line.delete(0,end+1);if(!value.isEmpty()){new JSONObject(value);emit(id,"message",value);}}}if(line.toString().trim().length()>0)throw new IOException("MCP 输出不完整");emit(id,"closed",true);}catch(Exception e){emit(id,"error","MCP stdio 输出无效或进程中断");}finally{pipes.remove(id,p);child.stop();}});io.execute(()->{try(InputStream in=child.stderr()){byte[] discard=new byte[4096];while(in.read(discard)!=-1){/* Do not expose process stderr, which may contain credentials. */}}catch(Exception ignored){}});io.execute(()->{try{child.await();}catch(Exception ignored){}});return new JSONObject().put("id",id);}
    void write(String id,String value)throws Exception {Pipe p=pipes.get(id);if(p==null)throw new IOException("MCP 进程已结束");server(p.server);if(value.length()>1048576||value.indexOf('\n')>=0)throw new IOException("无效 MCP 消息");new JSONObject(value);synchronized(p){p.child.stdin().write((value+"\n").getBytes(StandardCharsets.UTF_8));p.child.stdin().flush();}}
    void cancel(String id){HttpURLConnection c=http.remove(id);httpServers.remove(id);if(c!=null)io.execute(c::disconnect);Pipe p=pipes.remove(id);if(p!=null)p.child.stop();}
    private void stopServer(String server){for(Map.Entry<String,Pipe> e:pipes.entrySet())if(e.getValue().server.equals(server))cancel(e.getKey());for(Map.Entry<String,String> e:httpServers.entrySet())if(e.getValue().equals(server))cancel(e.getKey());}
    JSONObject handle(String operation,JSONObject a)throws Exception {if(operation.equals("extension.session")){String next=a.getString("session");if(next.length()>128||next.isEmpty())throw new IOException("MCP 会话无效");if(!next.equals(session)){disconnect();session=next;}return new JSONObject().put("ready",true);}if(operation.equals("extension.disconnect")){disconnect();return new JSONObject().put("closed",true);}if((operation.equals("extension.http")||operation.startsWith("extension.stdio."))&&(session.isEmpty()||!session.equals(a.optString("session"))))throw new IOException("MCP 工作会话已失效");switch(operation){case "extension.list":return snapshot();case "extension.save":return upsert(a);case "extension.toggle":return toggle(a.getString("id"),a.optBoolean("enabled"),false);case "extension.remove":return toggle(a.getString("id"),false,true);case "extension.http":http(a.getString("id"),a);return new JSONObject().put("started",true);case "extension.cancel":cancel(a.getString("id"));return new JSONObject().put("cancelled",true);case "extension.stdio.open":return open(a.getString("project"),a.getString("server"));case "extension.stdio.write":write(a.getString("id"),a.getString("message"));return new JSONObject().put("accepted",true);case "plugin.toggle":return pluginToggle(a.getString("id"),a.optBoolean("enabled"));case "plugin.remove":return pluginRemove(a.getString("id"));case "plugin.skill":return skill(a.getString("plugin"),a.getString("path"));case "plugin.builtin":return builtinSkill(a.getString("id"));case "plugin.from-url":return ExtensionImports.fromUrl(context,this,a.getString("url"));case "plugin.from-text":return ExtensionImports.fromText(context,this,a.optString("name"),a.getString("content"));default:throw new IOException("未知扩展操作");}}

    synchronized JSONObject install(Uri uri)throws Exception {if(records("plugins").length()>=16)throw new IOException("最多安装 16 个插件");if(!directory.isDirectory()&&!directory.mkdirs())throw new IOException("插件目录不可用");String id="plugin-"+UUID.randomUUID();File target=new File(directory,id);if(!target.mkdir())throw new IOException("无法创建插件目录");try(InputStream input=context.getContentResolver().openInputStream(uri);ZipInputStream zip=new ZipInputStream(input)){long total=0;int entries=0;ZipEntry e;while((e=zip.getNextEntry())!=null){if(++entries>1000)throw new IOException("插件文件过多");String name=e.getName();if(name.indexOf('\\')>=0||name.startsWith("/")||name.indexOf('\0')>=0)throw new IOException("插件路径无效");File f=new File(target,name).getCanonicalFile();if(!f.toPath().startsWith(target.getCanonicalFile().toPath())||f.equals(target))throw new IOException("插件包含越界路径");if(e.isDirectory()){if(!f.isDirectory()&&!f.mkdirs())throw new IOException("无法创建插件目录");continue;}if(!f.getParentFile().isDirectory()&&!f.getParentFile().mkdirs())throw new IOException("无法创建插件目录");try(OutputStream out=new FileOutputStream(f)){byte[] b=new byte[8192];int n;while((n=zip.read(b))!=-1){total+=n;if(total>33554432)throw new IOException("插件解压后超过 32 MB");out.write(b,0,n);}}}File base=target;File[] children=target.listFiles();if(children!=null&&children.length==1&&children[0].isDirectory())base=children[0];File manifest=null;for(String name:new String[]{"studio-plugin.json",".claude-plugin/plugin.json",".codex-plugin/plugin.json"}){File candidate=new File(base,name);if(candidate.isFile()){manifest=candidate;break;}}JSONObject info=manifest==null?ExtensionImports.detectedManifest(base):new JSONObject(read(manifest,65536));String relative=target.toPath().relativize(base.toPath()).toString().replace('\\','/');JSONObject plugin=new JSONObject().put("id",id).put("name",info.optString("name","已导入插件")).put("version",info.optString("version","未标注")).put("description",info.optString("description","")).put("root",relative).put("enabled",false).put("skills",scanSkills(base));JSONArray servers=new JSONArray(records("servers").toString());JSONObject mappings=info.optJSONObject("mcpServers");File mcp=new File(base,".mcp.json");if(mcp.isFile())mappings=new JSONObject(read(mcp,262144)).optJSONObject("mcpServers");if(mappings!=null){if(servers.length()+mappings.length()>16)throw new IOException("插件 MCP 服务超过 16 个上限");for(Iterator<String> keys=mappings.keys();keys.hasNext();){String name=keys.next();JSONObject value=new JSONObject(mappings.getJSONObject(name).toString()).put("id","mcp-"+UUID.randomUUID()).put("name",plugin.getString("name")+" / "+name).put("plugin",id).put("enabled",false);replacePluginPaths(value,base.getPath(),"/studio-plugins/"+id+(relative.isEmpty()?"":"/"+relative));servers.put(normalize(value));}}JSONArray plugins=new JSONArray(records("plugins").toString());plugins.put(plugin);save(new JSONObject(config.toString()).put("servers",servers).put("plugins",plugins));return snapshot();}catch(Exception e){removeTree(target);throw e;}}
    private static void replacePluginPaths(JSONObject value,String unused,String base)throws Exception {for(String key:new String[]{"command"})if(value.has(key))value.put(key,value.getString(key).replace("${CLAUDE_PLUGIN_ROOT}",base).replace("${CODEX_PLUGIN_ROOT}",base));JSONArray args=value.optJSONArray("args");if(args!=null)for(int i=0;i<args.length();i++)args.put(i,args.getString(i).replace("${CLAUDE_PLUGIN_ROOT}",base).replace("${CODEX_PLUGIN_ROOT}",base));}
    static JSONArray scanSkills(File base)throws Exception {JSONArray result=new JSONArray();collectSkills(base,base,0,result);return result;}
    private static void collectSkills(File base,File current,int depth,JSONArray result)throws Exception {if(depth>6||result.length()>=64||Files.isSymbolicLink(current.toPath()))return;File skill=new File(current,"SKILL.md");if(skill.isFile()){String content=read(skill,65536),name=ExtensionImports.metadata(content,"name");String relative=base.toPath().relativize(skill.toPath()).toString().replace('\\','/');result.put(new JSONObject().put("name",name.isEmpty()?current.getName():name).put("description",ExtensionImports.metadata(content,"description")).put("path",relative));}File[] children=current.listFiles();if(children!=null)for(File child:children)if(child.isDirectory()&&!Arrays.asList(".git","node_modules",".claude-plugin",".codex-plugin").contains(child.getName()))collectSkills(base,child,depth+1,result);}
    synchronized JSONObject builtinSkill(String key)throws Exception {String[] skill=ExtensionImports.preset(key);JSONObject builtins=config.optJSONObject("builtinSkills");String id=builtins==null?"":builtins.optString(key);for(int i=0;i<records("plugins").length();i++)if(id.equals(records("plugins").getJSONObject(i).optString("id")))return pluginToggle(id,true);JSONObject imported=ExtensionImports.fromText(context,this,skill[1],skill[3]);id=imported.getJSONArray("plugins").getJSONObject(imported.getJSONArray("plugins").length()-1).getString("id");JSONObject nextBuiltins=builtins==null?new JSONObject():new JSONObject(builtins.toString());nextBuiltins.put(key,id);JSONArray plugins=new JSONArray(records("plugins").toString());for(int i=0;i<plugins.length();i++)if(id.equals(plugins.getJSONObject(i).optString("id")))plugins.getJSONObject(i).put("builtin",key).put("description",skill[2]);save(new JSONObject(config.toString()).put("builtinSkills",nextBuiltins).put("plugins",plugins));return pluginToggle(id,true);}
    synchronized JSONObject pluginToggle(String id,boolean enabled)throws Exception {JSONArray plugins=new JSONArray(records("plugins").toString()),servers=new JSONArray(records("servers").toString());boolean found=false;for(int i=0;i<plugins.length();i++){JSONObject p=plugins.getJSONObject(i);if(id.equals(p.optString("id"))){p.put("enabled",enabled);found=true;}}if(!found)throw new IOException("插件不存在");for(int i=0;i<servers.length();i++){JSONObject s=servers.getJSONObject(i);if(id.equals(s.optString("plugin"))){s.put("enabled",enabled);stopServer(s.getString("id"));}}save(new JSONObject(config.toString()).put("plugins",plugins).put("servers",servers));return snapshot();}
    synchronized JSONObject pluginRemove(String id)throws Exception {if(!id.matches("plugin-[a-f0-9-]{36}"))throw new IOException("插件 ID 无效");JSONArray plugins=new JSONArray(),servers=new JSONArray();boolean found=false;for(int i=0;i<records("plugins").length();i++){JSONObject p=records("plugins").getJSONObject(i);if(id.equals(p.optString("id")))found=true;else plugins.put(p);}if(!found)throw new IOException("插件不存在");for(int i=0;i<records("servers").length();i++){JSONObject s=records("servers").getJSONObject(i);if(id.equals(s.optString("plugin")))stopServer(s.getString("id"));else servers.put(s);}save(new JSONObject(config.toString()).put("plugins",plugins).put("servers",servers));removeTree(new File(directory,id));return snapshot();}
    synchronized JSONObject skill(String id,String path)throws Exception {for(int i=0;i<records("plugins").length();i++){JSONObject p=records("plugins").getJSONObject(i);if(id.equals(p.optString("id"))&&p.optBoolean("enabled")){File base=new File(new File(directory,id),p.optString("root")).getCanonicalFile(),file=new File(base,path).getCanonicalFile();boolean registered=false;JSONArray skills=p.optJSONArray("skills");if(skills!=null)for(int s=0;s<skills.length();s++)registered|=path.equals(skills.getJSONObject(s).optString("path"));if(!file.toPath().startsWith(base.toPath())||!registered||!file.getName().equals("SKILL.md"))throw new IOException("技能路径无效");return new JSONObject().put("content",read(file,65536)).put("untrusted",true);}}throw new IOException("插件未启用或不存在");}
    static String read(File file,int limit)throws Exception {if(!file.isFile()||file.length()>limit)throw new IOException("插件文件不存在或超过容量");return new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8);}
    private static void removeTree(File file)throws IOException {File[] children=Files.isSymbolicLink(file.toPath())?null:file.listFiles();if(children!=null)for(File child:children)removeTree(child);Files.deleteIfExists(file.toPath());}
    synchronized void disconnect(){session="";for(String id:new ArrayList<>(http.keySet()))cancel(id);for(String id:new ArrayList<>(pipes.keySet()))cancel(id);}
    @Override public void close(){closed=true;for(String id:new ArrayList<>(http.keySet()))cancel(id);for(String id:new ArrayList<>(pipes.keySet()))cancel(id);io.shutdown();}
}
